c(29, "§Part 4 table (verbatim); §4.1 table (verbatim)", "insight", "Rating distribution (verbatim): " + table("# PART 4 — RATINGS ANALYSIS", 0) + " — bimodal: 59.26% at the top, 17.59% at the bottom, 22.15% in the middle three bands — 'the app produces two distinct experiences, not one mediocre one', and the fork is the paywall. Five-star drivers (segment rates, denominator 128) (verbatim): " + table("## 4.1 Five stars", 0) + " — the modal 5★ review is nine characters long and says 'Love it'; only 37 of 128 (28.91%) state a reason connected to using the product — those 37 are the real positive evidence", "n/a", "mixed", "5★ 59.26%; 1★ 17.59%; 37 substantive 5★", "none", "table", "generalisable", ["11557625143","12223735550","11966357701","13246223133","12525758438","11796162718"])
c(30, "§4.2 table (verbatim); §4.3; §4.4", "insight", "Four stars (19): the least informative band; only four explain the missing star and three name money or scope (verbatim): " + table("## 4.2 Four stars", 0) + " — two further 4★ register the cost and accept it, the only place a price mention sits above 3★ without a complaint. Three stars (17): the genuinely mixed band — price/gating with the product liked ('Great for using for daily chores. not great because you have to pay monthly'; 'Seems like a good program but dang! It costs too much. So I deleted it.'), scope gaps, and four contradictions. Two stars (14): where design praise and price rejection coexist — 'Es ist eigentlich sehr schön gemacht und gestaltet aber einfach zu teuer'; 'It is a good app well designed but cost abit of money' (the most recent review in the corpus, 2026-08-01)", "n/a", "mixed", "4★ 19; 3★ 17; 2★ 14", "none", "table", "generalisable", ["11604816252","12405257911","11855509579","13901287389","11491451108","12464351073","12097024072","11920445220","12214985598","12480621877","11735164096","12149341496","12594894710","14373191293","11601729790","12364644988"])
c(31, "§4.5 table (verbatim)", "monetization", "The one-star band is a monetization band (segment rates, denominator 38) (verbatim): " + table("## 4.5 One star", 0) + " — only seven of 38 (18.42%) are about anything else: two crashes, one custom-task limitation, one uninstall question, three with no stated reason; 'every serious operational failure in this report lives in this band, and it is 17.59% of the corpus. Fix the money flow and the majority of Mindway's one-star reviews have no cause left'", "n/a", "1★-burst", "31 of 38 1★ (81.58%) monetization", "none", "table", "generalisable", ["11789667295","11802262343","11590430878","11548752988","12006568991","12212460715","12524443211"])
c(32, "§4.6 table (verbatim); §4.7", "contradiction", "Rating / text contradictions — 8 (3.70%), disclosed not dropped (verbatim): " + table("## 4.6 Rating / text contradictions", 0) + " — they run in both directions and roughly cancel but are not symmetrical in kind: the four 3★ praise cases are short non-English or casual reviews where the star looks careless; the two 1★ neutral cases look like users rating the experience of being asked to rate; 'a star rating in this corpus is a weaker signal than usual; the theme counts are the reliable layer'. §4.7: no theme is purely one band — M_PAYWALL_BLOCK is 13×1★, 2×2★, 3×3★, 1×5★; M_PRICE_TOO_HIGH 0×5★ and 0×4★ but M_COST_NOTED 1×5★ 2×4★; M_PAID_CONFIRMED 11 of 13 at 1★ but one 4★ and one 3★; P_DESIGN mean 3.00", "n/a", "mixed", "8 (3.70%)", "none", "table", "generalisable", ["12228795122","12471944850","12508081500","12972889389","11590430878","12006568991","12212460715","12525758438"])
c(33, "§5.2 table (verbatim); §8.2 D2", "monetization", "Purchase triggers: direct evidence — capacity, in every case ('I want to create as many tasks as I want without having to pay'; the third task; more than one activity; the fourth task) — 'the paid trigger Mindway has actually built is you have run out of room'; only one reviewer describes a positive pull toward the paid tier and no reviewer names a Pro feature they wanted. Inferred triggers, labelled as inference (verbatim): " + table("## 5.2 Purchase triggers", 0) + " — none of these is what the paywall currently sells: the paywall sells task slots, the value users report is outcomes, structure and guidance — 'that mismatch is the core monetization finding of the report'; D2: sell the outcome, not the task slots", "count-based paywall", "purchase-driver", "0 name a Pro feature; 43 name outcomes", "product-rule", "table", "generalisable", ["13815532923","12741993650","12945940456","11602546791","11796162718"])
c(34, "§5.3 table (verbatim)", "monetization", "Upgrade barriers (verbatim): " + table("## 5.3 Upgrade barriers", 0) + " — asked to pay before the product has demonstrated anything (19 blocked + 3 interrupted: 'asked for money right away'; 'Stop playing games and get to plan'); price anchored against free tools already owned (6); price not visible before download (5); weekly pricing reads as expensive (€8/week, $7/week cited with outrage; the annual chosen to escape the weekly); five public warn-offs visible at the point of decision; trust damage from billing failures (11)", "n/a", "downgrade", "barrier table", "none", "table", "generalisable", ["11839657635","12502986885","11892038325","12274815966"])
